var t=[{id:"aWQ6MzEzMTk=",title:"Celebra\xE7\xE3o Animada dos Dados da Terra!",excerpt:"O sat\xE9lite de observa\xE7\xE3o di\xE1ria da Terra mais antigo da NASA \u2013 Terra \u2013 acabou de completar 25 anos, e com cinco instrumentos operando continuamente a bordo (a maioria capturando imagens simultaneamente), o Terra acumulou MUITOS dados ao longo dos anos (mais de 9.000 dias e contando!). Estes dados t\xEAm o potencial de esclarecer tudo, desde processos cient\xEDficos at\xE9 eventos \xFAnicos, ajudando a resolver problemas que afetam os humanos. Seu desafio \xE9 usar dados de qualquer um ou todos os cinco instrumentos do Terra para criar um produto animado que mostre uma hist\xF3ria de ci\xEAncia da Terra e enfatize os impactos em voc\xEA, sua comunidade e/ou o meio ambiente.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_9_Image.2e16d0ba.fill-300x250.jpg",alt:"NASA Space Apps 2025_Challenge 9"},categories:[{id:1,name:"Iniciante/Jovem",slug:"beginneryouth",color:"#2E96F5"},{id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"},{id:3,name:"Avan\xE7ado",slug:"advanced",color:"#8E1100"}],tags:["Anima\xE7\xE3o","Artes & Multim\xEDdia","An\xE1lise de Dados","Gest\xE3o de Dados","Visualiza\xE7\xE3o de Dados","Ci\xEAncias da Terra","Flora & Fauna","Sat\xE9lites Artificiais","Narrativa","Videografia/Fotografia","Clima"],slug:"animation-celebration-of-terra-data"},{id:"aWQ6MzEzMTI=",title:"Um Mundo Distante: Ca\xE7ando Exoplanetas com IA",excerpt:"Dados de v\xE1rias miss\xF5es espaciais de pesquisa de exoplanetas permitiram a descoberta de milhares de novos planetas fora do nosso sistema solar, mas a maioria destes exoplanetas foi identificada manualmente. Com avan\xE7os em intelig\xEAncia artificial e aprendizado de m\xE1quina (IA/ML), \xE9 poss\xEDvel analisar automaticamente grandes conjuntos de dados coletados por essas miss\xF5es para identificar exoplanetas. Seu desafio \xE9 criar um modelo de IA/ML treinado em um ou mais dos conjuntos de dados de exoplanetas de c\xF3digo aberto oferecidos pela NASA e que possa analisar novos dados para identificar exoplanetas com precis\xE3o.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_2_Image.2e16d0ba.fill-300x250.jpg",alt:"Space Apps 2025__Challenge 2"},categories:[{id:3,name:"Avan\xE7ado",slug:"advanced",color:"#8E1100"}],tags:["Intelig\xEAncia Artificial & Aprendizado de M\xE1quina","Programa\xE7\xE3o","An\xE1lise de Dados","Gest\xE3o de Dados","Visualiza\xE7\xE3o de Dados","Objetos Extrasolares","Planetas & Luas","Software","Explora\xE7\xE3o Espacial"],slug:"a-world-away-hunting-for-exoplanets-with-ai"},{id:"aWQ6MzEzMjY=",title:"BloomWatch: Uma Aplica\xE7\xE3o de Observa\xE7\xE3o da Terra para Fenologia Global de Flora\xE7\xE3o",excerpt:"Testemunhe o pulso da vida em nosso planeta! De esta\xE7\xE3o para esta\xE7\xE3o e de ano para ano, a vegeta\xE7\xE3o da Terra est\xE1 constantemente mudando, fornecendo informa\xE7\xF5es cr\xEDticas sobre esp\xE9cies de plantas, culturas, efeitos sazonais, fontes de p\xF3len e mudan\xE7as na fenologia das plantas (a rela\xE7\xE3o entre mudan\xE7as sazonais e fen\xF4menos clim\xE1ticos e biol\xF3gicos nas plantas). Seu desafio \xE9 aproveitar o poder das observa\xE7\xF5es terrestres da NASA para criar uma ferramenta visual din\xE2mica que exiba e/ou detecte eventos de flora\xE7\xE3o de plantas ao redor do globo\u2014assim como os polinizadores fazem\u2014e que avance solu\xE7\xF5es para monitoramento, previs\xE3o ou gest\xE3o da vegeta\xE7\xE3o.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_17_option_2.2e16d0ba.fill-300x250.jpg",alt:"NASA Space Apps 2025_Challenge 17"},categories:[{id:1,name:"Iniciante/Jovem",slug:"beginneryouth",color:"#2E96F5"},{id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"},{id:3,name:"Avan\xE7ado",slug:"advanced",color:"#8E1100"}],tags:["Anima\xE7\xE3o","Artes & Multim\xEDdia","Neg\xF3cios & Economia","An\xE1lise de Dados","Visualiza\xE7\xE3o de Dados","Ci\xEAncias da Terra","Flora & Fauna","Previs\xE3o","Realidade Virtual","Reda\xE7\xE3o & Comunica\xE7\xF5es"],slug:"bloomwatch-an-earth-observation-application-for-global-flowering-phenology"},{id:"aWQ6MzEzMTM=",title:"Construa um Motor de Conhecimento de Biologia Espacial",excerpt:"Permita uma nova era de explora\xE7\xE3o espacial humana! A NASA tem realizado experimentos de biologia no espa\xE7o h\xE1 d\xE9cadas, gerando uma quantidade tremenda de informa\xE7\xF5es que precisar\xE3o ser consideradas conforme os humanos se preparam para revisitar a Lua e explorar Marte. Embora esse conhecimento esteja publicamente dispon\xEDvel, pode ser dif\xEDcil para usu\xE1rios potenciais encontrar informa\xE7\xF5es que se relacionem aos seus interesses espec\xEDficos. Seu desafio \xE9 construir um painel din\xE2mico que aproveite intelig\xEAncia artificial (IA), grafos de conhecimento e/ou outras ferramentas para resumir um conjunto de publica\xE7\xF5es de bioci\xEAncias da NASA e permite aos usu\xE1rios explorar os impactos e resultados dos experimentos que essas publica\xE7\xF5es descrevem.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_3_image_2.2e16d0ba.fill-300x250.jpg",alt:"Space Apps 2025__Challenge 3"},categories:[{id:1,name:"Iniciante/Jovem",slug:"beginneryouth",color:"#2E96F5"},{id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"},{id:3,name:"Avan\xE7ado",slug:"advanced",color:"#8E1100"}],tags:["Intelig\xEAncia Artificial & Aprendizado de M\xE1quina","Gest\xE3o de Dados","Educa\xE7\xE3o","Flora & Fauna","Software","Reda\xE7\xE3o & Comunica\xE7\xF5es"],slug:"build-a-space-biology-knowledge-engine"},{id:"aWQ6MzEzMjA=",title:"Comercializando a \xD3rbita Terrestre Baixa (LEO)",excerpt:"\xC0 medida que a comercializa\xE7\xE3o do espa\xE7o acelera rapidamente, o futuro dos neg\xF3cios na \xF3rbita terrestre baixa (LEO) possui um potencial incr\xEDvel, mas tamb\xE9m apresenta desafios operacionais, regulamentares e ambientais significativos. Esta nova fronteira econ\xF4mica convida abordagens inovadoras e sustent\xE1veis para promover a viabilidade a longo prazo e a execu\xE7\xE3o respons\xE1vel. Seu desafio \xE9 conceitualizar e projetar um modelo de neg\xF3cio escal\xE1vel e sustent\xE1vel, acompanhado por um prot\xF3tipo, que explore as oportunidades \xFAnicas que a LEO oferece enquanto aborda as complexidades de operar no espa\xE7o.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_10_Image.2e16d0ba.fill-300x250.jpg",alt:"NASA Space Apps 2025_Challenge 10"},categories:[{id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"},{id:3,name:"Avan\xE7ado",slug:"advanced",color:"#8E1100"}],tags:["Neg\xF3cios & Economia","Design","\xD3rbita Terrestre","Ergonomia & Fatores Humanos","Habitats","Hardware","Sat\xE9lites Artificiais"],slug:"commercializing-low-earth-orbit-leo"},{id:"aWQ6MzEzMzA=",title:"Crie Seu Pr\xF3prio Desafio",excerpt:"Voc\xEA tem uma ideia que n\xE3o se encaixa exatamente em nenhum dos nossos desafios? Procurando experi\xEAncia para iniciantes? Este \xE9 o seu momento de sonhar grande e Criar Seu Pr\xF3prio Desafio! Seja criando um aplicativo, obra de arte, hist\xF3ria, li\xE7\xE3o, ferramenta ou explorando uma forma inovadora de usar dados da NASA, voc\xEA define o desafio. Observe que, embora alguns Eventos Locais possam oferecer pr\xEAmios para projetos 'Crie Seu Pr\xF3prio Desafio', este desafio n\xE3o \xE9 eleg\xEDvel para Avalia\xE7\xE3o Global, e os projetos n\xE3o se qualificam para Pr\xEAmios Globais.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Astronaut_Woody_Hoburg_takes_an_ou.2e16d0ba.fill-300x250.jpg",alt:"Astronaut Woody Hoburg takes an out-of-this-world space-selfie"},categories:[{id:1,name:"Iniciante/Jovem",slug:"beginneryouth",color:"#2E96F5"}],tags:[],slug:"create-your-own-challenge"},{id:"aWQ6MzEzMTc=",title:"Caminhos de Dados para Cidades Saud\xE1veis e Assentamentos Humanos",excerpt:"As mudan\xE7as clim\xE1ticas trazem novas complexidades a considerar para manter o bem-estar da sociedade e do meio ambiente nas cidades. Recursos naturais, ecossistemas e infraestrutura existente devem ser monitorados para garantir que a qualidade de vida humana permane\xE7a alta. Seu desafio \xE9 demonstrar como um planejador urbano pode usar dados de observa\xE7\xE3o da Terra da NASA para desenvolver estrat\xE9gias inteligentes para o crescimento da cidade que mantenham tanto o bem-estar das pessoas quanto do meio ambiente.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_7_Image_1.2e16d0ba.fill-300x250.jpg",alt:"NASA Space Apps 2025_Challenge 7"},categories:[{id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"},{id:3,name:"Avan\xE7ado",slug:"advanced",color:"#8E1100"}],tags:["Neg\xF3cios & Economia","An\xE1lise de Dados","Design","Ci\xEAncias da Terra","Ergonomia & Fatores Humanos","Habitats","Polui\xE7\xE3o","Res\xEDduos & Recursos"],slug:"data-pathways-to-healthy-cities-and-human-settlements"},{id:"aWQ6MzEzMjU=",title:"Mergulho Profundo: Hist\xF3rias de Dados Imersivas do Oceano ao C\xE9u",excerpt:"Observa\xE7\xF5es de sat\xE9lite revelam insights sobre nosso planeta natal din\xE2mico para cientistas, mas pessoas sem forma\xE7\xE3o em sensoriamento remoto frequentemente acham dif\xEDcil acessar as hist\xF3rias dentro desses conjuntos de dados. A pol\xEDtica de dados abertos da NASA torna essas observa\xE7\xF5es dispon\xEDveis para todos\u2014cientistas e n\xE3o-cientistas. Seu desafio \xE9 construir uma experi\xEAncia curta e imersiva de realidade virtual (VR) que aproveite os conjuntos de dados e visualiza\xE7\xF5es de observa\xE7\xE3o da Terra da NASA para dar vida \xE0s hist\xF3rias sobre os oceanos do nosso planeta, conectando uma audi\xEAncia ampla a esses dados, sua beleza e seu impacto. Usando visuais, \xE1udio espacial e at\xE9 elementos interativos, sua experi\xEAncia VR pode permitir aos usu\xE1rios mergulhar mais profundamente na hist\xF3ria oce\xE2nica em desenvolvimento da Terra.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_16_option_3.2e16d0ba.fill-300x250.jpg",alt:"NASA Space Apps 2025_Challenge 16"},categories:[{id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"},{id:3,name:"Avan\xE7ado",slug:"advanced",color:"#8E1100"}],tags:["Anima\xE7\xE3o","Artes & Multim\xEDdia","An\xE1lise de Dados","Gest\xE3o de Dados","Visualiza\xE7\xE3o de Dados","Ci\xEAncias da Terra","Habitats","Sat\xE9lites","Explora\xE7\xE3o Espacial","Narrativa","Realidade Virtual","Reda\xE7\xE3o & Comunica\xE7\xF5es"],slug:"deep-dive-immersive-data-stories-from-ocean-to-sky"},{id:"aWQ6MzEzMTQ=",title:"Aumente Seus Olhos!",excerpt:"Enquanto a tela do seu celular pode exibir cerca de tr\xEAs milh\xF5es de pixels de informa\xE7\xE3o e seu olho pode receber mais de dez milh\xF5es de pixels, as imagens da NASA do espa\xE7o s\xE3o ainda maiores! As miss\xF5es espaciais da NASA continuam a expandir os limites do que \xE9 tecnologicamente poss\xEDvel, fornecendo imagens e v\xEDdeos de alta resolu\xE7\xE3o da Terra, outros planetas e do espa\xE7o com bilh\xF5es ou at\xE9 trilh\xF5es de pixels. Seu desafio \xE9 criar uma plataforma que permita aos usu\xE1rios ampliar e reduzir nesses enormes conjuntos de dados de imagem, rotular caracter\xEDsticas conhecidas e descobrir novos padr\xF5es.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_4_Image.2e16d0ba.fill-300x250.jpg",alt:"NASA Space Apps 2025_Challenge 4"},categories:[{id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"}],tags:["Programa\xE7\xE3o","An\xE1lise de Dados","Gest\xE3o de Dados","Visualiza\xE7\xE3o de Dados","Objetos Extrasolares","Software","Explora\xE7\xE3o Espacial","Videografia/Fotografia","Desenvolvimento Web"],slug:"embiggen-your-eyes"},{id:"aWQ6MzEzMjQ=",title:"De EarthData \xE0 A\xE7\xE3o: Computa\xE7\xE3o em Nuvem com Dados de Observa\xE7\xE3o da Terra para Prever C\xE9us Mais Limpos e Seguros",excerpt:"A miss\xE3o TEMPO (Tropospheric Emissions: Monitoring of Pollution) da NASA est\xE1 revolucionando o monitoramento da qualidade do ar na Am\xE9rica do Norte, permitindo melhores previs\xF5es e reduzindo a exposi\xE7\xE3o a poluentes. Seu desafio \xE9 desenvolver um aplicativo baseado na web que preveja a qualidade do ar integrando dados TEMPO em tempo real com medi\xE7\xF5es de qualidade do ar baseadas em solo e dados meteorol\xF3gicos, notificando usu\xE1rios sobre m\xE1 qualidade do ar e ajudando a melhorar decis\xF5es de sa\xFAde p\xFAblica. As equipes s\xE3o encorajadas a utilizar novas tecnologias que permitam escalonamento cont\xEDnuo de computa\xE7\xE3o de dispositivos locais para sistemas em nuvem, melhorando a colabora\xE7\xE3o e simplificando a efici\xEAncia do trabalho.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_15_Image.2e16d0ba.fill-300x250.png",alt:"NASA Space Apps 2025_Challenge 15"},categories:[{id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"},{id:3,name:"Avan\xE7ado",slug:"advanced",color:"#8E1100"}],tags:["Intelig\xEAncia Artificial & Aprendizado de M\xE1quina","Neg\xF3cios & Economia","An\xE1lise de Dados","Ci\xEAncias da Terra","Previs\xE3o","Polui\xE7\xE3o","Clima","Desenvolvimento Web"],slug:"from-earthdata-to-action-cloud-computing-with-earth-observation-data-for-predicting-cleaner-safer-skies"},{id:"aWQ6MzEzMTY=",title:"Aplicativos do 25\xBA Anivers\xE1rio da Esta\xE7\xE3o Espacial Internacional",excerpt:"As tripula\xE7\xF5es a bordo da Esta\xE7\xE3o Espacial Internacional t\xEAm muitas oportunidades \xFAnicas! Elas testemunham vistas espetaculares da Terra da c\xFApula da esta\xE7\xE3o\u2014conhecida como 'a janela para o mundo'. Elas tamb\xE9m experimentam a aus\xEAncia de gravidade e saem da esta\xE7\xE3o em caminhadas espaciais, para as quais devem treinar extensivamente no Laborat\xF3rio de Flutuabilidade Neutra (NBL) no Sonny Carter Training Facility em Houston, Texas. Seu desafio \xE9 criar uma ferramenta visual que n\xE3o apenas ajude estudantes e o p\xFAblico a entender duas das experi\xEAncias sensoriais mais proeminentes na esta\xE7\xE3o (vis\xE3o e aus\xEAncia de gravidade) atrav\xE9s das lentes da c\xFApula e do NBL, mas tamb\xE9m os informe como essas experi\xEAncias \xFAnicas beneficiam os humanos na Terra.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_6_Iss_cupola.2e16d0ba.fill-300x250.jpg",alt:"NASA Space Apps 2025_Challenge 6"},categories:[{id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"},{id:3,name:"Avan\xE7ado",slug:"advanced",color:"#8E1100"}],tags:["Design","\xD3rbita Terrestre","Educa\xE7\xE3o","Ergonomia & Fatores Humanos","Jogos","Design Gr\xE1fico","Habitats","Sat\xE9lites Artificiais","Explora\xE7\xE3o Espacial"],slug:"international-space-station-25th-anniversary-apps"},{id:"aWQ6MzEzMTE=",title:"Loucura de Meteoros",excerpt:"Um asteroide pr\xF3ximo \xE0 Terra rec\xE9m-identificado, 'Impactor-2025', representa uma amea\xE7a potencial \xE0 Terra, mas temos as ferramentas para permitir que o p\xFAblico e os tomadores de decis\xE3o entendam e mitiguem seus riscos? Os conjuntos de dados da NASA incluem informa\xE7\xF5es sobre asteroides conhecidos e o United States Geological Survey fornece informa\xE7\xF5es cr\xEDticas que poderiam permitir modelar os efeitos de impactos de asteroides, mas esses dados precisam ser integrados para permitir visualiza\xE7\xE3o e tomada de decis\xE3o eficazes. Seu desafio \xE9 desenvolver uma ferramenta de visualiza\xE7\xE3o e simula\xE7\xE3o interativa que use dados reais para ajudar os usu\xE1rios a modelar cen\xE1rios de impacto de asteroides, prever consequ\xEAncias e avaliar estrat\xE9gias de mitiga\xE7\xE3o potenciais.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_1_Image.2e16d0ba.fill-300x250.jpg",alt:"Space Apps 2025_Challenge 1"},categories:[{id:1,name:"Iniciante/Jovem",slug:"beginneryouth",color:"#2E96F5"},{id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"},{id:3,name:"Avan\xE7ado",slug:"advanced",color:"#8E1100"}],tags:["Astrof\xEDsica","Programa\xE7\xE3o","An\xE1lise de Dados","Visualiza\xE7\xE3o de Dados","Resposta a Desastres","Objetos Extrasolares","Previs\xE3o","Explora\xE7\xE3o Espacial","Estat\xEDstica"],slug:"meteor-madness"},{id:"aWQ6MzEzMjc=",title:"Navegadores da Fazenda NASA: Usando Explora\xE7\xE3o de Dados NASA na Agricultura",excerpt:"A comunidade agr\xEDcola enfrenta o desafio de integrar tecnologia e dados para melhorar pr\xE1ticas de agricultura sustent\xE1vel. Simular atividades agr\xEDcolas chave como fertiliza\xE7\xE3o, irriga\xE7\xE3o e gest\xE3o de gado usando imagens de sat\xE9lite da NASA do mundo real e dados clim\xE1ticos pode permitir melhor compreens\xE3o dos impactos dessas vari\xE1veis na produ\xE7\xE3o de culturas. Seu desafio \xE9 criar um jogo educacional envolvente que utilize efetivamente os conjuntos de dados abertos da NASA para simular cen\xE1rios de agricultura e permite aos jogadores aprender como esses dados podem informar m\xE9todos agr\xEDcolas inovadores e sustent\xE1veis.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_18_Image.2e16d0ba.fill-300x250.png",alt:"NASA Space Apps 2025_Challenge 18"},categories:[{id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"},{id:3,name:"Avan\xE7ado",slug:"advanced",color:"#8E1100"}],tags:["Agricultura","Neg\xF3cios & Economia","An\xE1lise de Dados","Visualiza\xE7\xE3o de Dados","Ci\xEAncias da Terra","Educa\xE7\xE3o","Flora & Fauna","Jogos","Polui\xE7\xE3o","Narrativa"],slug:"nasa-farm-navigators-using-nasa-data-exploration-in-agriculture"},{id:"aWQ6MzEzMjI=",title:"Tubar\xF5es do Espa\xE7o",excerpt:"O oceano da Terra \xE9 um dos habitats mais poderosos em nosso universo, sustentando uma gama de vida que mant\xE9m ecossistemas e habitabilidade em todo o globo. \xC9 comum medir a atividade fotossint\xE9tica no oceano do espa\xE7o, mas muito mais desafiador rastrear predadores de topo. Seu desafio \xE9 criar uma estrutura matem\xE1tica para identificar tubar\xF5es e prever seus habitats de forrageamento usando dados de sat\xE9lite da NASA, e tamb\xE9m sugerir um novo modelo conceitual de uma etiqueta (um pequeno dispositivo eletr\xF4nico que pode ser anexado a um animal para rastrear e estudar seu movimento) que possa medir n\xE3o apenas onde os tubar\xF5es est\xE3o, mas o que eles est\xE3o comendo, e transmitir esses dados em tempo real de volta aos usu\xE1rios para permitir o desenvolvimento de modelos preditivos.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_13_Image.2e16d0ba.fill-300x250.png",alt:"NASA Space Apps 2025_Challenge 13"},categories:[{id:3,name:"Avan\xE7ado",slug:"advanced",color:"#8E1100"}],tags:["Anima\xE7\xE3o","An\xE1lise de Dados","Visualiza\xE7\xE3o de Dados","Design","Ci\xEAncias da Terra","Flora & Fauna","Previs\xE3o","Hardware"],slug:"sharks-from-space"},{id:"aWQ6MzEzMTg=",title:"SpaceTrash Hack: Revolucionando a Reciclagem em Marte",excerpt:"Durante uma miss\xE3o hipot\xE9tica de tr\xEAs anos para Marte e volta, uma tripula\xE7\xE3o de oito pessoas acumularia 12.600 kg de res\xEDduos inorg\xE2nicos, ou lixo, incluindo v\xE1rios materiais de embalagem, t\xEAxteis e materiais estruturais. Este cen\xE1rio cria uma necessidade premente de reciclar materiais dispon\xEDveis, em vez de executar os processos caros e ineficientes de transportar recursos adicionais da Terra e/ou enviar lixo de volta \xE0 Terra. Conforme os humanos se preparam para explorar mundos desconhecidos no futuro, seu desafio \xE9 projetar sistemas sustent\xE1veis que poderiam gerenciar, reutilizar ou reciclar res\xEDduos inorg\xE2nicos ('lixo') que s\xE3o trazidos para e/ou acumulados na superf\xEDcie de Marte.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_8_Image.2e16d0ba.fill-300x250.png",alt:"NASA Space Apps 2025_Challenge 8"},categories:[{id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"},{id:3,name:"Avan\xE7ado",slug:"advanced",color:"#8E1100"}],tags:["Design","Ergonomia & Fatores Humanos","Habitats","Planetas & Luas","Explora\xE7\xE3o Espacial","Res\xEDduos & Recursos"],slug:"spacetrash-hack-revolutionizing-recycling-on-mars"},{id:"aWQ6MzEzMjM=",title:"Hist\xF3rias Estelares: Clima Espacial Atrav\xE9s dos Olhos dos Terr\xE1queos",excerpt:"Embora o Sol esteja a 150 milh\xF5es de quil\xF4metros de dist\xE2ncia do nosso planeta, a atividade solar pode impactar significativamente nossas vidas di\xE1rias. O 'clima espacial'\u2014as varia\xE7\xF5es que ocorrem no ambiente espacial entre o Sol e a Terra\u2014pode impactar tecnologias no espa\xE7o e na Terra. Seu desafio \xE9 escrever e ilustrar uma hist\xF3ria digital infantil que explique o que \xE9 o clima espacial e os impactos variados que tem em diferentes pessoas como agricultores, pilotos, astronautas, operadores de rede el\xE9trica e o p\xFAblico geral. Voc\xEA pode contar a hist\xF3ria da perspectiva de uma pessoa impactada pelo clima espacial ou do ponto de vista de uma erup\xE7\xE3o solar ou eje\xE7\xE3o de massa coronal (CME) conforme se aproxima da Terra.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_14_Image.2e16d0ba.fill-300x250.png",alt:"NASA Space Apps 2025_Challenge 14"},categories:[{id:1,name:"Iniciante/Jovem",slug:"beginneryouth",color:"#2E96F5"},{id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"},{id:3,name:"Avan\xE7ado",slug:"advanced",color:"#8E1100"}],tags:["Anima\xE7\xE3o","Artes & Multim\xEDdia","Resposta a Desastres","Educa\xE7\xE3o","Clima Espacial","Narrativa","Sol","Clima"],slug:"stellar-stories-space-weather-through-the-eyes-of-earthlings"},{id:"aWQ6MzEzMjE=",title:"Atrav\xE9s do Espelho do Radar: Revelando Processos da Terra com SAR",excerpt:"Como Alice no Pa\xEDs das Maravilhas, vamos viajar pela toca do coelho... para revelar um mundo que se parece com nosso planeta Terra... mas n\xE3o exatamente! Usando radar de abertura sint\xE9tica (SAR), podemos imagear o mundo emitindo pulsos de radar em dire\xE7\xE3o \xE0 Terra e registrando a energia que \xE9 refletida de volta ap\xF3s os sinais interagirem com a superf\xEDcie da Terra. Seu desafio \xE9 baixar dados SAR de m\xFAltiplas frequ\xEAncias ou m\xFAltiplas polariza\xE7\xF5es para uma \xE1rea de estudo interessante de sua escolha\u2014por exemplo, sua cidade natal, uma zona \xFAmida tropical, manto de gelo, inc\xEAndio florestal, bairro inundado, erup\xE7\xE3o vulc\xE2nica, etc.\u2014e usar esses dados para desenvolver hip\xF3teses sobre os impulsores f\xEDsicos operando l\xE1.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_11_Image.2e16d0ba.fill-300x250.jpg",alt:"NASA Space Apps 2025_Challenge 11"},categories:[{id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"},{id:3,name:"Avan\xE7ado",slug:"advanced",color:"#8E1100"}],tags:["Anima\xE7\xE3o","An\xE1lise de Dados","Visualiza\xE7\xE3o de Dados","Ci\xEAncias da Terra","Sat\xE9lites Artificiais","Narrativa"],slug:"through-the-radar-looking-glass-revealing-earth-processes-with-sar"},{id:"aWQ6MzEzMjg=",title:"Vai Chover no Meu Desfile?",excerpt:"Se voc\xEA est\xE1 planejando um evento ao ar livre\u2014como f\xE9rias, ou uma caminhada em uma trilha, ou pesca em um lago\u2014seria bom saber as chances de tempo adverso para o hor\xE1rio e local que voc\xEA est\xE1 considerando. Existem muitos tipos de dados de observa\xE7\xE3o da Terra que podem fornecer informa\xE7\xF5es sobre condi\xE7\xF5es meteorol\xF3gicas para um local e dia espec\xEDficos do ano. Seu desafio \xE9 construir um aplicativo com uma interface personalizada que permite aos usu\xE1rios conduzir uma consulta customizada para lhes dizer a probabilidade de condi\xE7\xF5es 'muito quentes', 'muito frias', 'muito ventosas', 'muito molhadas' ou 'muito desconfort\xE1veis' para o local e hor\xE1rio que especificam.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_19_Option_3.2e16d0ba.fill-300x250.jpg",alt:"NASA Space Apps 2025_Challenge 19"},categories:[{id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"}],tags:["Programa\xE7\xE3o","An\xE1lise de Dados","Visualiza\xE7\xE3o de Dados","Previs\xE3o","Software","Clima","Desenvolvimento Web"],slug:"will-it-rain-on-my-parade"},{id:"aWQ6MzEzMTU=",title:"Sua Casa no Espa\xE7o: O Criador de Layout de Habitat",excerpt:"Habitats espaciais s\xE3o 'casas no espa\xE7o' que mant\xEAm os membros da tripula\xE7\xE3o saud\xE1veis e capazes de executar sua miss\xE3o. Seja localizado em uma superf\xEDcie planet\xE1ria ou no espa\xE7o, os habitats devem suportar fun\xE7\xF5es cr\xEDticas como gest\xE3o de res\xEDduos, controle t\xE9rmico, suporte \xE0 vida, comunica\xE7\xF5es, energia, armazenamento, armazenamento e preparo de alimentos, cuidados m\xE9dicos, sono e exerc\xEDcio. Conceitos de habitat espacial podem envolver uma variedade diversa de materiais, geometrias e layouts. Seu desafio \xE9 criar uma ferramenta visual que permita aos usu\xE1rios definir a forma/volume de um habitat espacial e explorar poss\xEDveis op\xE7\xF5es de layout.",featuredImage:{url:"https://assets.spaceappschallenge.org/media/images/Challenge_5_Image.2e16d0ba.fill-300x250.png",alt:"NASA Space Apps 2025_Challenge 5"},categories:[{id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"}],tags:["Design","\xD3rbita Terrestre","Ergonomia & Fatores Humanos","Jogos","Design Gr\xE1fico","Habitats","Sat\xE9lites Artificiais","Explora\xE7\xE3o Espacial","Res\xEDduos & Recursos"],slug:"your-home-in-space-the-habitat-layout-creator"}];var s={id:1,name:"Iniciante/Jovem",slug:"beginneryouth",color:"#2E96F5"},a={id:2,name:"Intermedi\xE1rio",slug:"intermediate",color:"#E43700"},e={id:3,name:"Avan\xE7ado",slug:"advanced",color:"#8E1100"};var d=[{id:"2026-01",title:"Abandonados, mas N\xE3o Esquecidos: Contando a Hist\xF3ria dos Equipamentos Descartados da NASA na Lua e em Marte",excerpt:"Desde a d\xE9cada de 1960, a NASA deixou equipamentos espalhados pelo sistema solar \u2014 na Lua, em Marte e no espa\xE7o profundo. De rovers e instrumentos que conclu\xEDram suas miss\xF5es cient\xEDficas a sondas que ainda viajam para longe da Terra, esse hardware varia muito tanto em prop\xF3sito quanto em n\xEDvel atual de funcionamento. Seu desafio \xE9 contar a hist\xF3ria de parte ou de todo esse equipamento, apresentando a entusiastas do espa\xE7o em idade escolar o hardware e a ci\xEAncia que ele tornou poss\xEDvel.",featuredImage:{url:"assets/desafios/2026/abandoned-but-not-forgotten.jpg",alt:"Modelos dos rovers Sojourner, Spirit/Opportunity e Curiosity no solo marciano"},categories:[a,s],tags:["Astrof\xEDsica","Planetas & Luas","Explora\xE7\xE3o Espacial"],slug:"abandoned-but-not-forgotten-storytelling-about-nasas-discarded-equipment-on-the-moon-and-mars"},{id:"2026-02",title:"Seja um Detetive de Tend\xEAncias do Sistema Terrestre!",excerpt:'Mudan\xE7as acontecem o tempo todo no sistema ambiental interconectado da Terra e, quando seguem uma dire\xE7\xE3o consistente \u2014 subindo ou descendo, aumentando ou diminuindo, engrossando ou afinando \u2014, as vari\xE1veis medidas refletem isso. Mas uma vari\xE1vel pode apresentar tend\xEAncia em um sentido numa regi\xE3o e no sentido oposto em outra, mesmo quando o mesmo processo governa as duas. Seu desafio \xE9 encontrar e examinar vari\xE1veis medidas por miss\xF5es da NASA ou produzidas por modelos da NASA, visualizar como elas mudam ao longo do tempo e determinar o que est\xE1 mudando, onde est\xE1 mudando, quanto est\xE1 mudando e se essas mudan\xE7as s\xE3o o que os cientistas chamam de "significativas".',featuredImage:{url:"assets/desafios/2026/be-an-earth-system-trend-detective.jpg",alt:"Globo terrestre dividido entre imagem de sat\xE9lite e sa\xEDda colorida de modelo clim\xE1tico"},categories:[e],tags:["Ci\xEAncias da Terra","Software"],slug:"be-an-earth-system-trend-detective"},{id:"2026-03",title:"Construa um Treinador de Miss\xF5es para Astronautas Mirins",excerpt:"Conte\xFAdos STEM com tema espacial costumam simplificar demais os trade-offs de engenharia que definem uma miss\xE3o real, ou apresent\xE1-los em um n\xEDvel complexo demais para prender a aten\xE7\xE3o de um jovem aprendiz. Poucas ferramentas tornam esses trade-offs ao mesmo tempo tang\xEDveis e divertidos. Seu desafio \xE9 projetar e construir um jogo ou aplicativo interativo que permita a estudantes administrar uma base lunar ou marciana, equilibrando demandas concorrentes como suporte \xE0 vida, blindagem contra radia\xE7\xE3o, energia e produ\xE7\xE3o de alimentos, para que vivenciem na pr\xE1tica as decis\xF5es que determinam o fracasso ou o sucesso de uma miss\xE3o.",featuredImage:{url:"assets/desafios/2026/build-a-junior-astronaut-mission-trainer.jpg",alt:"Silhueta de uma crian\xE7a observando a Terra pela janela de uma espa\xE7onave"},categories:[a,s],tags:["Jogos","Planetas & Luas","Software","Explora\xE7\xE3o Espacial","Sol"],slug:"build-a-junior-astronaut-mission-trainer"},{id:"2026-04",title:"Navegador de Miss\xF5es Lunares CLPS",excerpt:"Miss\xF5es ao polo sul da Lua enfrentam restri\xE7\xF5es extremas de ilumina\xE7\xE3o e comunica\xE7\xE3o, e planej\xE1-las exige coordena\xE7\xE3o cuidadosa entre as equipes de ci\xEAncia e de engenharia. J\xE1 existem ferramentas para determinar as posi\xE7\xF5es do Sol e da Terra em locais candidatos a pouso, mas suas interfaces complicadas dificultam avaliar informa\xE7\xF5es cr\xEDticas com efici\xEAncia. Seu desafio \xE9 criar uma ferramenta ou aplica\xE7\xE3o intuitiva que permita a planejadores de miss\xE3o, educadores e ao p\xFAblico comparar rapidamente locais e datas de pouso, visualizando as posi\xE7\xF5es do Sol e da Terra em rela\xE7\xE3o ao horizonte para avaliar o potencial de gera\xE7\xE3o de energia e as janelas de comunica\xE7\xE3o direta com a Terra.",featuredImage:{url:"assets/desafios/2026/clps-lunar-mission-browser.jpg",alt:"Superf\xEDcie craterada do polo sul da Lua"},categories:[e,a,s],tags:["Ci\xEAncias da Terra"],slug:"clps-lunar-mission-browser"},{id:"2026-05",title:"Crie um Software de Monitoramento de Sa\xFAde para Astronautas em Miss\xF5es Espaciais",excerpt:"Miss\xF5es de longa dura\xE7\xE3o exp\xF5em astronautas \xE0 radia\xE7\xE3o espacial, ao isolamento e confinamento, \xE0 gravidade alterada e a um ambiente fechado e hostil, o que pode provocar altera\xE7\xF5es imunol\xF3gicas, perda \xF3ssea, eventos cardiovasculares e problemas de sa\xFAde comportamental. Em miss\xF5es longas, os astronautas carregam boa parte da responsabilidade de identificar essas mudan\xE7as em si mesmos. Seu desafio \xE9 construir um software de monitoramento de sa\xFAde que re\xFAna indicadores de sa\xFAde e permita aos astronautas avaliar o pr\xF3prio estado de sa\xFAde e agir a partir dele.",featuredImage:{url:"assets/desafios/2026/create-health-monitoring-software.jpg",alt:"Astronauta se exercitando na Esta\xE7\xE3o Espacial Internacional ao lado de um painel de sinais vitais"},categories:[a],tags:["Software","Explora\xE7\xE3o Espacial"],slug:"create-health-monitoring-software-for-astronauts-on-space-missions"},{id:"2026-06",title:"Dan\xE7ando com os SARs",excerpt:"A superf\xEDcie da Terra \xE9 uma dan\xE7a infinita de processos naturais e atividades humanas, mas essas mudan\xE7as costumam ser dif\xEDceis de visualizar, entender e comunicar. Da perda de \xE1reas \xFAmidas a inc\xEAndios florestais, terremotos, atividades agr\xEDcolas, movimenta\xE7\xE3o de geleiras e muito mais, a Terra vive uma valsa constante de mudan\xE7as na superf\xEDcie. Seu desafio \xE9 construir uma aplica\xE7\xE3o interativa que use dados de sensoriamento remoto por radar da miss\xE3o NISAR (NASA-ISRO Synthetic Aperture Radar) para rastrear e visualizar um ou mais tipos de mudan\xE7a de superf\xEDcie em locais ao redor do mundo.",featuredImage:{url:"assets/desafios/2026/dancing-with-the-sars.jpg",alt:"Imagem de radar de abertura sint\xE9tica mostrando mudan\xE7as na superf\xEDcie terrestre em falsas cores"},categories:[e,a],tags:["Ci\xEAncias da Terra"],slug:"dancing-with-the-sars"},{id:"2026-07",title:"Virada no Campo: Adaptando Fazendas com Dados da NASA",excerpt:"Agricultores no mundo todo lidam com temperaturas em transforma\xE7\xE3o, mudan\xE7as nos padr\xF5es de chuva, escassez de \xE1gua, eventos clim\xE1ticos extremos e queda na sa\xFAde do solo. Essas press\xF5es dificultam a escolha de rota\xE7\xF5es de culturas que protejam as lavouras, conservem \xE1gua e sustentem a resili\xEAncia a longo prazo. Seu desafio \xE9 criar uma ferramenta de apoio \xE0 decis\xE3o que use observa\xE7\xF5es da Terra da NASA junto com informa\xE7\xF5es locais de solo, caracter\xEDsticas das culturas e prioridades dos produtores, ajudando agricultores a explorar estrat\xE9gias de rota\xE7\xE3o capazes de fortalecer a sa\xFAde do solo e adaptar suas fazendas \xE0s novas condi\xE7\xF5es.",featuredImage:{url:"assets/desafios/2026/field-shift-adapting-farms.jpg",alt:"Agricultora examinando gr\xE3os em uma lavoura ao p\xF4r do sol, ao lado de um piv\xF4 de irriga\xE7\xE3o"},categories:[e,a],tags:["Artes & Multim\xEDdia","Ci\xEAncias da Terra","Software"],slug:"field-shift-adapting-farms-with-nasa-data"},{id:"2026-08",title:"Chama em Queda Livre: Seguran\xE7a contra Inc\xEAndio com IA a partir de Dados de Combust\xE3o em Microgravidade",excerpt:"H\xE1 d\xE9cadas a NASA estuda como chamas e inc\xEAndios se comportam em microgravidade, acumulando no caminho um vasto acervo de dados experimentais. Esse conhecimento importa mais do que nunca enquanto nos preparamos para voltar \xE0 Lua e seguir rumo a Marte, mas o volume de resultados os torna dif\xEDceis de encontrar, comparar e entender. Seu desafio \xE9 criar um painel interativo movido a intelig\xEAncia artificial que resuma, classifique e interprete esses achados para entregar insights de seguran\xE7a contra inc\xEAndio para a explora\xE7\xE3o espacial humana.",featuredImage:{url:"assets/desafios/2026/flame-in-freefall.jpg",alt:"Chama esf\xE9rica queimando em microgravidade durante experimento da NASA"},categories:[e,a],tags:["Explora\xE7\xE3o Espacial"],slug:"flame-in-freefall-ai-powered-fire-safety-insights-from-microgravity-combustion-data"},{id:"2026-09",title:"Harmoniza\xE7\xE3o dos Focos de Calor do MODIS e do VIIRS",excerpt:"Entender como a atividade de queimadas se distribui pelo planeta ao longo do tempo \u2014 incluindo inc\xEAndios florestais e queimadas agr\xEDcolas intensas o bastante para serem detectadas por sensores de sat\xE9lite \u2014 permite antecipar per\xEDodos cr\xEDticos, orientar esfor\xE7os de monitoramento e melhorar a resposta a inc\xEAndios. Os sat\xE9lites rastreiam focos de calor ativos h\xE1 mais de duas d\xE9cadas, mas o registro est\xE1 fragmentado entre sensores cujos dados n\xE3o podem ser comparados diretamente, deixando os gestores de inc\xEAndio sem um retrato consistente de quando e onde as queimadas ocorreram. Seu desafio \xE9 construir uma aplica\xE7\xE3o web que harmonize esses registros em um calend\xE1rio de atividade de queimadas baseado em focos de calor ativos, permitindo que equipes de alerta precoce e de resposta a emerg\xEAncias, cientistas e gestores de terras examinem padr\xF5es hist\xF3ricos de fogo, condi\xE7\xF5es at\xEDpicas e per\xEDodos cr\xEDticos dentro de uma \xE1rea de interesse selecionada.",featuredImage:{url:"assets/desafios/2026/harmonization-of-modis-and-viirs-hot-spots.jpg",alt:"Imagem de sat\xE9lite em falsas cores mostrando cicatriz de inc\xEAndio e foco de calor ativo"},categories:[e,a],tags:[],slug:"harmonization-of-modis-and-viirs-hot-spots"},{id:"2026-10",title:"Identifique Locais na Terra An\xE1logos \xE0s Futuras Bases Permanentes na Lua e em Marte",excerpt:"A escolha de futuros locais de pouso e de bases lunares depende de muitos fatores, entre eles topografia, geologia, ambiente e recursos dispon\xEDveis. Lugares na Terra com caracter\xEDsticas an\xE1logas \xE0s da Lua ou de Marte \u2014 o Deserto do Atacama, a Cratera Haughton, o Vale da Morte \u2014 permitem que equipes de miss\xE3o testem equipamentos e m\xE9todos antes do voo; no entanto, esses s\xEDtios an\xE1logos terrestres n\xE3o est\xE3o totalmente caracterizados. Seu desafio \xE9 usar dados abertos da Terra, da Lua e de Marte da NASA e de outras ag\xEAncias espaciais para identificar e caracterizar novos an\xE1logos terrestres para futuras bases ou locais de pouso, recorrendo a desertos, regi\xF5es polares, terrenos vulc\xE2nicos e \xE1ridos, cavernas e outros ambientes que compartilhem condi\xE7\xF5es com a superf\xEDcie lunar ou marciana.",featuredImage:{url:"assets/desafios/2026/identify-earth-locations-analog.jpg",alt:"Nascer da Terra visto acima do horizonte lunar"},categories:[e,a,s],tags:["Ci\xEAncias da Terra","Planetas & Luas","Software","Explora\xE7\xE3o Espacial"],slug:"identify-earth-locations-that-analog-the-permanent-moon-base-locations-and-mars"},{id:"2026-11",title:"Guia de Sobreviv\xEAncia Interplanet\xE1rio: Mapa Marciano",excerpt:"A NASA explora Marte de forma rob\xF3tica h\xE1 d\xE9cadas, estudando seu ambiente extremo, mapeando sua superf\xEDcie e coletando muitos tipos de dados. Longe de casa, os primeiros astronautas da NASA a pisar em Marte v\xE3o querer o melhor mapa poss\xEDvel, com informa\xE7\xF5es sobre os detalhes de suas rotas e destinos, atualiza\xE7\xF5es sobre as condi\xE7\xF5es atuais e os dados necess\xE1rios para cumprir a miss\xE3o com rapidez e seguran\xE7a. Seu desafio \xE9 criar uma vis\xE3o integrada e em camadas de um local ou rota na superf\xEDcie marciana que re\xFAna dados de m\xFAltiplas miss\xF5es cient\xEDficas da NASA e possa ajudar um explorador humano a planejar e executar uma caminhada marciana bem-sucedida, fazendo ci\xEAncia nova e empolgante pelo caminho.",featuredImage:{url:"assets/desafios/2026/interplanetary-survival-guide-martian-map.jpg",alt:"Concep\xE7\xE3o art\xEDstica de astronautas e um m\xF3dulo de pouso na superf\xEDcie de Marte"},categories:[a],tags:["Software","Explora\xE7\xE3o Espacial"],slug:"interplanetary-survival-guide-martian-map"},{id:"2026-12",title:"Planeta X e SPHEREx",excerpt:"Desde 2025, a miss\xE3o SPHEREx da NASA vem mapeando todo o c\xE9u a cada seis meses em 102 bandas de luz infravermelha pr\xF3xima, devolvendo imagens de mais de um bilh\xE3o de objetos. Cometas, asteroides, estrelas, an\xE3s marrons e at\xE9 novos planetas se revelam ao mudar de posi\xE7\xE3o entre as imagens, mas ningu\xE9m consegue vasculhar sozinho todo esse volume de dados. Seu desafio \xE9 criar uma ferramenta web aberta ao p\xFAblico para exibir imagens do c\xE9u obtidas pela miss\xE3o SPHEREx, tornando f\xE1cil para qualquer pessoa ver rapidamente como elas mudam ao longo do tempo.",featuredImage:{url:"assets/desafios/2026/planet-x-and-spherex.jpg",alt:"Concep\xE7\xE3o art\xEDstica do observat\xF3rio espacial SPHEREx em \xF3rbita da Terra"},categories:[e],tags:["Explora\xE7\xE3o Espacial"],slug:"planet-x-and-spherex"},{id:"2026-13",title:"Jogo de Design de Miss\xF5es Espaciais",excerpt:"Projetar uma miss\xE3o espacial exige considerar cuidadosamente demandas concorrentes, como objetivos da miss\xE3o, projeto da espa\xE7onave, instrumentos cient\xEDficos, ve\xEDculos lan\xE7adores, or\xE7amentos, energia, massa, comunica\xE7\xF5es e restri\xE7\xF5es orbitais. Para estudantes que raramente t\xEAm a chance de experimentar uma miss\xE3o inteira, do conceito \xE0 opera\xE7\xE3o, esses trade-offs costumam permanecer abstratos. Seu desafio \xE9 criar um jogo interativo que permita aos participantes projetar, gerenciar e simular uma miss\xE3o espacial completa, tomando decis\xF5es de engenharia, administrando recursos limitados e avaliando como cada escolha molda o sucesso da miss\xE3o.",featuredImage:{url:"assets/desafios/2026/space-mission-design-game.jpg",alt:"Astronauta em caminhada espacial tendo a Terra ao fundo"},categories:[a,s],tags:["Jogos"],slug:"space-mission-design-game"},{id:"2026-14",title:"A Jukebox de Informa\xE7\xF5es da Terra",excerpt:'O Earth Information Center (EIC) da NASA produz visualiza\xE7\xF5es impressionantes do nosso planeta em transforma\xE7\xE3o, mas apresentar a ci\xEAncia da Terra apenas por meio de imagens limita quem consegue alcan\xE7\xE1-la. Convidamos voc\xEA a tornar essa ci\xEAncia complexa acess\xEDvel, envolvente e multissensorial, traduzindo o que se v\xEA em som. Seu desafio \xE9 construir uma "Jukebox da Terra" \u2014 uma interface, script ou aplica\xE7\xE3o que combine os quadros visuais do Earth Information Center com sonifica\xE7\xF5es din\xE2micas geradas em tempo real.',featuredImage:{url:"assets/desafios/2026/the-earth-information-jukebox.jpg",alt:"Pessoa diante de uma instala\xE7\xE3o imersiva com proje\xE7\xE3o da Terra e vegeta\xE7\xE3o luminosa"},categories:[a,s],tags:["Artes & Multim\xEDdia","Ci\xEAncias da Terra","Software"],slug:"the-earth-information-jukebox"}];var n=2026,r=[{year:2026,tagsLabel:"Temas",challenges:d},{year:2025,tagsLabel:"Habilidades Sugeridas",challenges:t}],h=r.map(o=>o.year);function m(o){return r.find(i=>i.year===o)??r[0]}function A(o,i){return `https://www.spaceappschallenge.org/${o}/challenges/${i}/`}var b=m(n).challenges;
